 update eldervale_private.settings set revision=revision+1 where id returning revision into rev;
 update eldervale_private.entities set deleted=true,revision=rev where data->>'generation'='town-life-v1' and not deleted;
 for k,v in select * from jsonb_each(plan->'routes') loop
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('x',s->0,'z',s->1,'wait',s->2,'act',s->3,'face',s->4,'hold',s->5)) order by ord) into route from jsonb_array_elements(v->'r') with ordinality e(s,ord);
  update eldervale_private.entities set data=data||jsonb_strip_nulls(jsonb_build_object('route',route,'x',route->0->'x','z',route->0->'z','name',v->'n')),revision=rev where not deleted and data->>'generation'='seeded-world-v2' and data->>'seed'='241916600' and data->>'generatedKey'=k;
  if not found then raise exception 'Seeded actor % not found',k;end if;
 end loop;
 for p in select value from jsonb_array_elements(plan->'props') loop
  insert into eldervale_private.entities(revision,data) values(rev,jsonb_build_object('kind','object','name',p->4,'scale',1,'level',1,'hp',1,'damage',0,'attackSpeed',2.4,'roam',0,'respawn',0,'attackable',false,'hostile',false,'template',p->0,'x',p->1,'z',p->2,'yaw',p->3,'generation','town-life-v1','seed',241916600,'town',p->5));
 end loop;
 update eldervale_private.realm_actors set route_step=null,roam_x=null,roam_z=null,roam_pause_until=null where jsonb_typeof(data->'route')='array';
end $$;
